type Writable<T> = { -readonly [K in keyof T]: T[K] };

/** src/main.ts sets this (localStorage) when a save crashed the start and was set aside; Game tells the player once. */
export const RECOVERED_FLAG = 'winterland.recovered';

/** Longest step the real-time loop will take (tab switches, hitches). */
const MAX_DT = 1 / 20;

export interface DebugApi {
  game: Game;
  ctx: GameContext;
  /** Gameplay composition root (stations, NPC queues, pads, progression). */
  level: Level;
  /** Read-only tuning tables (bots/tests derive positions from these instead of hard-coding). */
  config: {
    LAYOUT: typeof LAYOUT;
    PADS: typeof PADS;
    ECONOMY: typeof ECONOMY;
    PLAYER: typeof PLAYER;
    TIMING: typeof TIMING;
    UPGRADES: typeof UPGRADES;
    CREW: typeof CREW;
    VILLAGE: typeof VILLAGE;
    DEMAND: typeof DEMAND;
    QUARTERS: typeof QUARTERS;
    RIDGE: typeof RIDGE;
    PRESTIGE: typeof PRESTIGE;
    BUSINESSES: typeof BUSINESSES;
    TOWN: typeof TOWN;
    AMENITIES: typeof AMENITIES;
    HAPPINESS: typeof HAPPINESS;
    PRIORITIES: typeof PRIORITIES;
  };
  state(): Record<string, unknown>;
  pause(): void;
  resume(): void;
  /** Advance the simulation by `seconds` in fixed steps without rendering, then render once. */
  simulate(seconds: number, dt?: number): Record<string, unknown>;
  render(): void;
  /** Screen-space move override (x right, y up); pass null to release. */
  setMove(x: number | null, y?: number): void;
  /** Force hold-to-interact held (true), released (false) or live input (null). */
  setInteract(on: boolean | null): void;
  /** Autopilot the player toward a world XZ point (cleared on arrival). */
  moveTo(x: number, z: number): void;
  teleport(x: number, z: number): void;
  /** Camera zoom at once (1 = default, < 1 shows more of the world; screenshots). */
  cameraZoom(mult: number): void;
  addMoney(n: number): void;
  skipIntro(): void;
  unlock(id: PadId): void;
  /** Shop purchase as if from the panel (spends money). False if not possible. */
  buy(id: UpgradeId): boolean;
  /** Jump an upgrade to a level for free (tests). */
  setUpgrade(id: UpgradeId, level: number): void;
  /** Open the village gate now. */
  revealVillage(): void;
  /** Set plot `plot` (−1 = Great Lodge) to `tier` at once (tests). */
  buildPlot(plot: number, tier: number): void;
  /** Set the crew bunkhouse to `tier` (−1 = none) at once (tests). */
  buildQuarters(tier: number): void;
  /** Wave 9: open the Market Town now / choose + finish lot `lot` as building `id` (plays the build moment). */
  revealTown(): void;
  buildTown(lot: number, id: BusinessId): void;
  /** Wave 12: complete a square amenity instantly. */
  buildAmenity(id: AmenityId): void;
  /** Start the next season (prestige) now: writes the new-season save and reloads. */
  newSeason(): void;
  /** Wave 13: start a world event / offer a contract now (tests). */
  startEvent(kind: EventKind, seconds?: number): void;
  offerContract(kind?: ItemKind): void;
  /** Start a rush hour now (tests). */
  startRush(seconds?: number): void;
  /** Jump the day/night clock to cycle share `p` (0..1; 0.75 = deep night). */
  setTimeOfDay(p: number): void;
  /** 0.9.0: open every era up to n (2..10) instantly, as if each expansion were paid. */
  unlockEra(n: number): void;
  /** 0.9.0: a fully built machine on era n's slot (false if not possible). */
  buildMachine(n: number, slot: number, id: string): boolean;
  /** 0.9.0: a fully built city building on district n's lot (false if not possible). */
  buildCity(n: number, lot: number, id: string): boolean;
  /** 0.9.0 climb (docs/EXPANSION.md §E): build the village out and the Great Lodge (no finale card), opening the climb. */
  climb(): void;
  /** Era n's gate checklist (default: the next era). */
  gate(n?: number): EraGate;
  /** Every upgrade of the eras reached to shown level `shown` (crews hired), for free. */
  setAllUpgrades(shown: number): void;
  /** Best settlement level `L` (era 1: up to 5; from era 2 up to SETTLEMENT.max; needs Winterland to show). */
  setSettlement(L: number): void;
  /** 0.9.0: fast travel to a travelPoints() id ('yard', 'town', 'region:3', 'district:5'). */
  travel(id: string): boolean;
  /** Write the save now; returns what was written (null when saving is off: `?fresh`, reset, no storage). */
  save(): SaveData | null;
  /** The save that would be written now (not written). */
  saveData(): SaveData;
  /** Delete the save (the running game keeps going; the next autosave writes a new one). */
  clearSave(): void;
  /** Offline earnings this game would get after `seconds` away (for tests). */
  offlinePreview(seconds: number): { amount: number; seconds: number };
}

declare global {
  interface Window {
    __WINTERLAND__?: DebugApi;
  }
}

export class Game {
  readonly ctx: GameContext;
  private readonly updatables: Updatable[] = [];
  private pendingRemovals = new Set<Updatable>();
  private readonly juice: JuiceDirector;
  private readonly level: Level;
  private running = false;
  private paused = false;
  private lastTime = 0;
  /** Frame cap; frames arriving early are skipped (sim and render) so the sim never slows (MAX_DT is 50 ms). */
  fpsCap: FpsCap = readFpsCap();
  private lastFrame = 0;
  /** Saving is off for `?fresh` pages and after a reset (until the reload). */
  private saving: boolean;
  private saveTimer: number = SAVE.interval;
  /** 0.9.6: seconds until the save on disk is next copied into the rolling backups (core/saveVault.ts). */
  private backupTimer: number = SAVE.backupInterval;
  private readonly sales: SalesMeter;

  constructor(container: HTMLElement, hudRoot: HTMLElement) {
    const renderer = new Renderer(container);
    const events = new EventBus<GameEvents>();
    const tweens = new TweenManager();
    // Load BEFORE anything is built: every system initialises itself from state (see docs/DESIGN.md).
    const fresh = freshRequested();
    this.saving = !fresh;
    const read: SaveRead = fresh ? { kind: 'none' } : readSave();
    const save = read.kind === 'ok' ? read.data : null;
    // 0.9.6 (S5): a save that can't be opened is never replaced by a fresh game without a copy of its exact text.
    const notices = this.saveNotices(read);
    const state = createGameState();
    if (save) {
      mergeState(state, save.state);
      sanitizeState(state);
    }
    const migration = migrateState(state, !save, { salesRate: save?.salesRate ?? 0, upgrades: (save?.state as { upgrades?: unknown } | undefined)?.upgrades, saved: save?.state, world: save?.world });
    const startMoney = save ? Math.min(Number.MAX_SAFE_INTEGER, save.money + migration.refund + migration.masteryPayout) : ECONOMY.startMoney;
    const economy = new Economy(events, state, startMoney);
    const upgrades = new Upgrades(state, economy, events);
    const colliders = new ColliderWorld();
    const input = new Input(renderer.domElement);
    const cameraRig = new CameraRig(renderer.camera);

    // Built progressively in dependency order (see GameContext docs), then frozen as read-only.
    const ctx = {
      scene: renderer.scene,
      camera: renderer.camera,
      renderer,
      events,
      tweens,
      state,
      economy,
      upgrades,
      colliders,
      input,
      cameraRig,
      dayNight: new DayNight(state, events),
      rush: new RushHours(state, events),
      quests: new Quests(state, economy, events),
      worldEvents: new WorldEvents(state, events, () => ctx.dayNight.darkness),
      contracts: new Contracts(state, economy, events),
      time: { elapsed: 0, frame: 0 },
      addUpdatable: (u: Updatable) => {
        this.pendingRemovals.delete(u);
        if (!this.updatables.includes(u)) this.updatables.push(u);
      },
      removeUpdatable: (u: Updatable) => {
        this.pendingRemovals.add(u);
      },
    } as Writable<GameContext>;
    this.ctx = ctx;
    ctx.market = new Market(ctx); // 0.9.0 (reads ctx.upgrades / state lazily)

    ctx.particles = new Particles(ctx);
    ctx.audio = new AudioFX();
    ctx.hud = new HUD(ctx, hudRoot);
    ctx.items = new ItemPool(ctx);
    ctx.flights = new FlightSystem(ctx);
    ctx.zones = new ZoneSystem(ctx);
    ctx.environment = new Environment(ctx);
    ctx.player = new Player(ctx);
    ctx.occlusion = new OcclusionFade(ctx); // 0.9.3: before the Level, whose buildings and pads register with it
    this.juice = new JuiceDirector(ctx);
    new Fireworks(ctx); // wave 9: era-up fireworks (self-registers as an updatable)
    this.level = new Level(ctx);
    if (save) this.level.restoreWorld(save.world);
    new GateTracker(ctx); // 0.9.0 climb: computed 'gate:progress' (seeded from the loaded world, so a load is silent)
    this.sales = new SalesMeter(ctx, save?.salesRate ?? 0);
    ctx.market.setSalesRate(() => this.sales.rate); // 0.9.6: investment caps follow the factories' income

    input.onFirstGesture(() => ctx.audio.unlock());
    cameraRig.follow(ctx.player.object);
    cameraRig.resize(renderer.width, renderer.height);
    cameraRig.snapToTarget();
    ctx.hud.setMoney(economy.money, false);

    window.addEventListener('resize', () => this.resize());
    window.visualViewport?.addEventListener('resize', () => this.resize());
    window.addEventListener('pagehide', () => this.save());
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') this.save();
    });
    events.on('game:reset', () => this.reset());
    // wave 10: keyboard shortcuts and zoom become events; the HUD and the camera listen
    input.onShortcut((s) => {
      if (s === 'escape') events.emit('ui:escape', {});
      else if (s === 'mute') events.emit('ui:mute', {});
      else if (s === 'fullscreen') events.emit('ui:fullscreen', {});
      else events.emit('camera:zoom', { delta: s === 'zoomIn' ? 0.1 : -0.1 });
    });
    input.onZoom((delta) => events.emit('camera:zoom', { delta }));
    events.on('settings:fps', ({ cap }) => this.setFpsCap(cap));
    events.on('save:restore', ({ text }) => this.restore(text));
    events.on('save:restoreBackup', ({ key }) => this.restoreBackup(key));
    events.on('game:quit', () => this.quit());
    events.on('camera:zoom', ({ delta }) => cameraRig.setUserZoom(cameraRig.userZoom + delta));
    events.on('season:new', () => this.newSeason());
    if (debugAllowed()) this.installDebugApi();
    this.level.start();

    if (save) {
      const away = offlineEarnings(save, Date.now());
      if (away.amount > 0) {
        // Credit NOW and write it down at once: an autosave / pagehide before the player taps the card would
        // otherwise rewrite savedAt and the earnings would vanish. The card is only informational; the new
        // savedAt also makes a second credit from the same absence impossible.
        ctx.economy.add(away.amount);
        this.save();
        ctx.hud.showOfflineEarnings(away.amount, away.seconds, () => {
          ctx.events.emit('offline:collected', { amount: away.amount }); // coin burst only
        });
      }
    }
    // 0.9.6 migrations changed the save (the refund is already in the wallet): write it down now, like offline earnings
    if (migration.applied.length > 0) this.save();
    const welcome = refundNotice(migration);
    if (welcome) notices.push(welcome);
    const resources = resourcesNotice(migration);
    if (resources) notices.push(resources);
    for (const n of notices) ctx.hud.showNotice(n);
  }

  /**
   * Keep what was on disk safe before anything is written over it, and say what happened: an unreadable save's exact
   * text is kept (or, if even that fails, saving stays off so the original is never overwritten); a save from a newer
   * build is snapshotted; the save this session starts from goes into the rolling backups. Also picks up the
   * crash-rescue flag left by src/main.ts.
   */
  private saveNotices(read: SaveRead): Notice[] {
    const out: Notice[] = [];
    const download = (raw: string, prefix: string) => (): false => {
      void exportText(raw, saveFileName(new Date(), prefix));
      return false; // keep the card open
    };
    if (read.kind === 'unreadable') {
      const kept = keepUnreadable(read.raw);
      // A save from a newer build is left exactly where it is: updating the game will open it. A corrupt one is set
      // aside (kept) so the fresh game may save; if the copy failed, nothing is saved at all.
      if (!kept || read.reason === 'newer-format') this.saving = false;
      out.push({
        icon: 'shield',
        title: 'Your save is safe',
        lines:
          read.reason === 'newer-format'
            ? [
                'Your save was made by a newer version of Winterland, so this copy started a fresh game.',
                'Your save is untouched and nothing here will be saved over it. Update Winterland to keep playing it.',
              ]
            : kept
              ? ["Winterland couldn't open your last save, so it started a fresh game.", 'An exact copy of the old save is kept, so nothing is lost. You can download it here.']
              : ["Winterland couldn't open your last save, so it started a fresh game.", 'Saving is paused so the old save is never overwritten. Download a copy before you reset.'],
        buttons: [{ label: 'Download', style: 'grey', onTap: download(read.raw, 'winterland-unreadable-save') }, { label: 'OK' }],
      });
    } else if (read.kind === 'ok') {
      pushBackup(read.raw);
      if (read.newer) {
        snapshotBefore(read.raw, 'newer');
        out.push({
          icon: 'shield',
          title: 'A save from a newer version',
          lines: [
            `This save was made by Winterland ${read.newer}, and this copy is ${GAME_VERSION}. Anything added after ${GAME_VERSION} may be lost if you keep playing here.`,
            'A copy of it as it was is kept in Settings, Game, Earlier saves.',
          ],
        });
      }
    }
    try {
      if (localStorage.getItem(RECOVERED_FLAG)) {
        localStorage.removeItem(RECOVERED_FLAG);
        out.push({
          icon: 'shield',
          title: 'Your save is safe',
          lines: ["Your save stopped Winterland from starting, so it started a fresh game instead.", 'The old save is kept: you can bring it back from Settings, Game, Earlier saves.'],
        });
      }
    } catch {
      /* no storage */
    }
    return out;
  }

  /** The save as it would be written now. */
  saveData(): SaveData {
    const c = this.ctx;
    return {
      v: SAVE.version,
      game: GAME_VERSION,
      savedAt: Date.now(),
      // Cash bundles still flying back to the wallet are not banked yet (CashStack.inFlightValue).
      money: c.economy.money + c.player.back.inFlightValue,
      state: c.state,
      world: this.level.snapshotWorld(),
      salesRate: this.sales.rate,
    };
  }

  /** Write the save (no-op when saving is off). */
  save(): SaveData | null {
    if (!this.saving) return null;
    const data = this.saveData();
    return writeSave(data) ? data : null;
  }

  /**
   * 0.9.6: before a Reset, a Restore or a New Season replaces the save, write the latest progress and keep it as the
   * "before" backup (Settings → Game → Earlier saves brings it back). Saving stops here: the pagehide save on the way
   * out would otherwise write the old game over whatever replaces it.
   */
  private keepBefore(why: string): void {
    this.save();
    this.saving = false;
    snapshotBefore(readRawSave(), why);
  }

  /** Settings → Reset: wipe the save and start over (the old one stays in Earlier saves). */
  private reset(): void {
    this.keepBefore('reset');
    clearSave();
    location.reload();
  }

  /** Settings → Restore save: keep the current one, write the text, reload. */
  private restore(text: string): void {
    if (parseSave(text).kind !== 'ok') {
      this.ctx.hud.toast("That file isn't a Winterland save.", { small: true });
      return;
    }
    const was = this.saving;
    this.keepBefore('restore');
    try {
      localStorage.setItem(SAVE.key, text);
    } catch {
      this.saving = was;
      this.ctx.hud.toast("Couldn't store the save.", { small: true });
      return;
    }
    location.reload();
  }

  /** Settings → Earlier saves: bring back one of the kept copies (core/saveVault.ts). */
  private restoreBackup(key: string): void {
    const text = readBackup(key);
    if (!text) {
      this.ctx.hud.toast("That earlier save isn't there any more.", { small: true });
      return;
    }
    this.restore(text);
  }

  /** Settings → Save & quit (desktop app): write the save, then close the app. Stays open if the save failed. */
  private quit(): void {
    const d = desktop();
    if (!d?.quit) return;
    if (this.saving && !this.save()) {
      this.ctx.hud.toast("Couldn't save just now", { sub: 'Your game is still open. Try again in a moment.', duration: 4 });
      return;
    }
    this.saving = false; // nothing may write after the final save
    d.quit();
  }

  /** After the finale: start the next season (prestige) from a fresh save and reload. */
  private newSeason(): void {
    this.keepBefore('season');
    if (!writeSave(newSeasonSave(this.ctx.state, Date.now()))) {
      // Storage is full / blocked: reloading would restart the old season without the bonus. Stay put.
      this.saving = true;
      this.ctx.hud.toast("Couldn't save the new season", { sub: 'Check your browser storage and try again', duration: 4 });
      return;
    }
    location.reload();
  }

  /** Start the real-time loop. */
  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      requestAnimationFrame(loop);
      if (this.fpsCap) {
        // allow a little slack so a 60 Hz display under a 60 cap doesn't drop to 30 from jitter
        if (now - this.lastFrame < 1000 / this.fpsCap - 2) return;
        this.lastFrame = now;
      }
      const dt = Math.min((now - this.lastTime) / 1000, MAX_DT);
      this.lastTime = now;
      if (!this.paused && dt > 0) this.step(dt);
      this.ctx.renderer.render();
    };
    requestAnimationFrame(loop);
  }

  /** Settings → Display: 0 (uncapped), 30 or 60. Persisted. */
  setFpsCap(cap: FpsCap): void {
    this.fpsCap = cap;
    writeFpsCap(cap);
  }

  /** One simulation step. */
  step(dt: number): void {
    const c = this.ctx;
    c.time.elapsed += dt;
    c.time.frame++;
    c.state.playTime += dt;

    c.input.update();
    c.player.update(dt);
    c.zones.update(dt);
    this.level.update(dt);
    c.dayNight.update(dt);
    c.rush.update(dt);
    c.quests.update(dt);
    c.worldEvents.update(dt);
    c.contracts.update(dt);
    c.market.update(dt);
    this.flushRemovals();
    for (let i = 0; i < this.updatables.length; i++) {
      const u = this.updatables[i]!;
      if (!this.pendingRemovals.has(u)) u.update(dt);
    }
    this.flushRemovals();
    c.flights.update(dt);
    c.tweens.update(dt);
    c.particles.update(dt);
    c.environment.update(dt);
    this.juice.update(dt);
    c.cameraRig.update(dt);
    c.renderer.setShadowFocus(c.cameraRig.target);
    c.hud.update(dt);

    this.saveTimer -= dt;
    this.backupTimer -= dt;
    if (this.saveTimer <= 0) {
      this.saveTimer = SAVE.interval;
      if (this.backupTimer <= 0 && this.saving) {
        // copy the save on disk into the rolling backups just before it is overwritten
        this.backupTimer = SAVE.backupInterval;
        const raw = readRawSave();
        if (raw) pushBackup(raw);
      }
      this.save();
    }
  }

  /** Fast-forward the simulation (tests). */
  simulate(seconds: number, dt = 1 / 60): void {
    if (!(dt > 0) || !Number.isFinite(dt)) dt = 1 / 60; // a zero step would never advance the loop
    const steps = Math.max(0, Math.round(seconds / dt));
    for (let i = 0; i < steps; i++) this.step(dt);
    this.ctx.renderer.render();
  }

  resize(): void {
    const r = this.ctx.renderer;
    r.resize();
    this.ctx.cameraRig.resize(r.width, r.height);
  }

  snapshot(): Record<string, unknown> {
    const c = this.ctx;
    const p = c.player.position;
    return {
      t: Math.round(c.time.elapsed * 100) / 100,
      phase: c.state.phase,
      // Cash bundles still flying back to the wallet are not banked yet (CashStack.inFlightValue).
      money: c.economy.money + c.player.back.inFlightValue,
      player: { x: Math.round(p.x * 100) / 100, z: Math.round(p.z * 100) / 100 },
      arms: { log: c.player.arms.count('log'), crate: c.player.arms.count('crate'), size: c.player.arms.size },
      cashBundles: c.player.back.count('cash'),
      flights: c.flights.activeCount,
      liveItems: c.items.liveCount,
      unlocked: { ...c.state.unlocked },
      padsVisible: { ...c.state.padsVisible },
      stats: { ...c.state.stats },
      upgrades: { ...c.state.upgrades },
      village: { revealed: c.state.village.revealed, population: c.state.village.population, level: c.state.village.level },
      level: this.level.snapshot(),
    };
  }

  private flushRemovals(): void {
    if (this.pendingRemovals.size === 0) return;
    for (let i = this.updatables.length - 1; i >= 0; i--) {
      if (this.pendingRemovals.has(this.updatables[i]!)) this.updatables.splice(i, 1);
    }
    this.pendingRemovals.clear();
  }

  private installDebugApi(): void {
    const ctx = this.ctx;
    window.__WINTERLAND__ = {
      game: this,
      ctx,
      level: this.level,
      config: { LAYOUT, PADS, ECONOMY, PLAYER, TIMING, UPGRADES, CREW, VILLAGE, DEMAND, QUARTERS, RIDGE, PRESTIGE, BUSINESSES, TOWN, AMENITIES, HAPPINESS, PRIORITIES },
      state: () => this.snapshot(),
      pause: () => {
        this.paused = true;
      },
      resume: () => {
        this.paused = false;
        this.lastTime = performance.now();
      },
      simulate: (seconds: number, dt?: number) => {
        this.simulate(seconds, dt);
        return this.snapshot();
      },
      render: () => ctx.renderer.render(),
      setInteract: (on: boolean | null) => {
        ctx.input.interactOverride = on;
      },
      setMove: (x: number | null, y = 0) => {
        ctx.input.override = x === null ? null : new THREE.Vector2(x, y);
      },
      moveTo: (x: number, z: number) => {
        ctx.player.autopilot = new THREE.Vector3(x, 0, z);
      },
      teleport: (x: number, z: number) => {
        ctx.player.teleport(x, z);
        ctx.cameraRig.snapToTarget();
      },
      cameraZoom: (mult: number) => ctx.cameraRig.setZoom(mult, 0),
      unlockEra: (n: number) => {
        for (let k = Math.max(2, ctx.state.eras.age + 1); k <= n; k++) this.level.eras.unlock(k, true);
      },
      buildMachine: (n: number, slot: number, id: string) => this.level.eras.build(n, slot, id, true),
      buildCity: (n: number, lot: number, id: string) => this.level.city.build(n, lot, id, true),
      travel: (id: string) => {
        const p = travelPoints(ctx.state).find((t) => t.id === id);
        if (!p) return false;
        ctx.events.emit('travel:request', { x: p.x, z: p.z, label: p.label });
        return true;
      },
      climb: () => {
        const v = this.level.village;
        v.reveal();
        ctx.state.flags.finale = true; // the Lodge without its finale card (screenshots, tests)
        for (let i = 0; i < ctx.state.village.plots.length; i++) v.debugBuild(i, VILLAGE.tiers.length - 1);
        if (!climbOpen(ctx.state)) v.debugBuild(-1, 0);
      },
      gate: (n?: number) => eraGate(ctx.state, n ?? ctx.state.eras.age + 1),
      setAllUpgrades: (shown: number) => {
        const age = Math.max(1, ctx.state.eras.age);
        for (const id of ctx.upgrades.ids) {
          const def = UPGRADES[id];
          if (introEra(def) <= age) ctx.upgrades.setLevel(id, Math.max(0, shown - base(def)));
        }
        ctx.events.emit('village:changed', { population: ctx.state.village.population, level: ctx.state.village.level });
      },
      setSettlement: (L: number) => {
        const e = ctx.state.eras;
        e.settlement = Math.max(0, Math.min(e.age >= 2 ? SETTLEMENT.max : SETTLEMENT.band, Math.round(L)));
        ctx.events.emit('settlement:changed', { level: settlementLevel(ctx.state), cityPopulation: cityPopulation(ctx.state) });
      },
      addMoney: (n: number) => ctx.economy.add(n),
      skipIntro: () => this.level.skipIntro(),
      unlock: (id: PadId) => this.level.forceUnlock(id),
      buy: (id: UpgradeId) => ctx.upgrades.buy(id),
      setUpgrade: (id: UpgradeId, level: number) => ctx.upgrades.setLevel(id, level),
      revealVillage: () => this.level.village.reveal(),
      buildPlot: (plot: number, tier: number) => this.level.village.debugBuild(plot, tier),
      buildQuarters: (tier: number) => this.level.quarters.debugBuild(tier),
      revealTown: () => this.level.town.reveal(false),
      buildTown: (lot: number, id: BusinessId) => this.level.town.debugBuild(lot, id),
      buildAmenity: (id: AmenityId) => this.level.town.debugBuildAmenity(id),
      newSeason: () => ctx.events.emit('season:new', {}),
      startRush: (seconds?: number) => ctx.rush.start(seconds),
      startEvent: (kind: EventKind, seconds?: number) => ctx.worldEvents.start(kind, seconds),
      offerContract: (kind?: ItemKind) => ctx.contracts.offer(kind),
      setTimeOfDay: (p: number) => {
        ctx.state.clock = Math.max(0, Math.min(1, p)) * DAYNIGHT.cycleSeconds;
      },
      save: () => this.save(),
      saveData: () => this.saveData(),
      clearSave: () => clearSave(),
      offlinePreview: (seconds: number) =>
        offlineEarnings({ ...this.saveData(), savedAt: Date.now() - seconds * 1000 }, Date.now()),
    };
  }
}

/** 0.9.7: the one-off card for a save past era 5 whose eras got their own resources (core/resourcesV2.ts). */
function resourcesNotice(m: MigrationReport): Notice | null {
  if (m.resourcesAge < 5) return null;
  const lines = ['Forge Flats now runs on iron pellets and coke: your pig iron is iron pellets now, and the Steel Mill takes 2 pellets + 1 coke.'];
  if (m.resourcesAge >= 10) {
    lines.push('Neural Plateau now runs on rare earth and helium-3: your data shards are rare earth, your Fusion Plants are Helium Skimmers (same level), and the new Fusion Reactor turns helium-3 into fusion cells.');
    if (m.reactor === 'build') lines.push('Build a Fusion Reactor in Neural Plateau to keep AI cores coming. If the plot is full, open a machine\'s MANAGE card and demolish one to free a slot.');
    else if (m.reactor === 'kept') lines.push('One Fusion Plant stayed as your Fusion Reactor, so your line keeps running.');
  }
  lines.push('Everything you owned and every level you bought came along. The new goods\' Fine upgrades start fresh.');
  return { icon: 'star', title: 'New resources in the late eras', lines, buttons: [{ label: 'Lovely!' }] };
}

/** The one-off "welcome to the new rule" card for a save whose levels past 10 were refunded (null when none were). */
function refundNotice(m: MigrationReport): Notice | null {
  if (m.refundedLevels <= 0 && m.tradeLevels <= 0) return null;
  const lines = ['Every upgrade now tops out at Lv 10, in every era.'];
  if (m.refundedLevels > 0) lines.push(`The ${m.refundedLevels.toLocaleString('en-US')} level${m.refundedLevels === 1 ? '' : 's'} you had bought past Lv 10 ${m.refundedLevels === 1 ? 'is' : 'are'} refunded in full.`);
  // 0.9.6 decision 9: Trade merged into each material's Fine upgrade (core/salesMerge.ts)
  if (m.tradeLevels > 0) lines.push(`Trade and Fine are now one upgrade per material. Each kept your best level, and the ${m.tradeLevels.toLocaleString('en-US')} Trade level${m.tradeLevels === 1 ? '' : 's'} it no longer needs ${m.tradeLevels === 1 ? 'is' : 'are'} refunded in full.`);
  lines.push('Your refund:');
  const n: Notice = { icon: 'coin', title: 'Welcome to the new level rule', lines, amount: m.refund + m.masteryPayout, buttons: [{ label: 'Lovely!' }] };
  const pct = Math.round((m.masteryHad - 1) * 100);
  if (m.masteryPayout > 0) {
    n.after = [`That includes ${formatMoney(m.masteryPayout)} for your Mastery bonus (+${pct}% on sales), now retired: about what it would have earned you over one era of play.`];
  } else if (m.masteryMult > 1.0001) {
    n.after = [`Your Mastery bonus stays with you for good: +${Math.round((m.masteryMult - 1) * 100)}% on every sale.`];
  }
  return n;
}
